import{_ as o,o as c,c as n,a5 as a}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"Local run architecture","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/local-run-architecture.md","filePath":"architecture/local-run-architecture.md"}'),s={name:"architecture/local-run-architecture.md"};function t(i,e,r,p,d,l){return c(),n("div",null,[...e[0]||(e[0]=[a(`<h1 id="local-run-architecture" tabindex="-1">Local run architecture <a class="header-anchor" href="#local-run-architecture" aria-label="Permalink to &quot;Local run architecture&quot;">​</a></h1><p>Ghi lại cách stack local thực sự lắp ráp, khác README gốc (README mô tả 1 file <code>docker-compose.yml</code> gộp — file này không tồn tại).</p><h2 id="compose-file-split" tabindex="-1">Compose file split <a class="header-anchor" href="#compose-file-split" aria-label="Permalink to &quot;Compose file split&quot;">​</a></h2><p><code>docker/</code> có 3 file compose độc lập, ghép bằng <code>-f</code>:</p><ul><li><code>docker-compose.infra.yml</code> — hạ tầng nền: postgres, redis, rabbitmq, chromadb, neo4j. Không mở port ra host (trừ khi có overlay dev).</li><li><code>docker-compose.dev.yml</code> — overlay chỉ thêm <code>ports:</code> cho các service trên (để connect từ host) + thêm service <code>pgadmin</code>.</li><li><code>docker-compose.apps.yml</code> — 5 service ứng dụng: api-gateway, business-service, ai-service, publisher-service, web-dashboard. Build từ Dockerfile của từng repo sibling (<code>../../brandhub-*</code>).</li></ul><p><code>scripts/run-compose.bat</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docker compose -f docker-compose.infra.yml -f docker-compose.dev.yml up -d          # mặc định</span></span>
<span class="line"><span>docker compose -f docker-compose.infra.yml -f docker-compose.apps.yml -f docker-compose.dev.yml up -d   # mode &quot;full&quot;</span></span></code></pre></div><p>Lý do tách: dev thường không cần build lại 5 app image (chạy <code>mvn spring-boot:run</code>/<code>npm run dev</code> trực tiếp cho hot-reload), chỉ cần infra. <code>full</code> dùng khi cần test nguyên cụm Docker (staging-like).</p><h2 id="mongodb-khong-co-trong-compose" tabindex="-1">MongoDB không có trong compose <a class="header-anchor" href="#mongodb-khong-co-trong-compose" aria-label="Permalink to &quot;MongoDB không có trong compose&quot;">​</a></h2><p><code>business-service</code> có biến <code>MONGODB_URI</code>/<code>MONGODB_DATABASE</code> nhưng không có service <code>mongo</code> nào trong <code>docker-compose.infra.yml</code>. Kết luận: Mongo dùng cloud (Atlas), không self-host local. <code>docs/database/init-mongo.js</code> tồn tại nhưng chạy tay nhắm vào cluster Atlas, không phải qua <code>docker-entrypoint-initdb.d</code>.</p><h2 id="dependency-chain-khi-len-full-stack" tabindex="-1">Dependency chain khi lên full stack <a class="header-anchor" href="#dependency-chain-khi-len-full-stack" aria-label="Permalink to &quot;Dependency chain khi lên full stack&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>postgres/redis/rabbitmq (healthy)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>business-service ──▶ (Postgres, Redis, RabbitMQ, Mongo Atlas)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>api-gateway ──▶ business-service + ai-service (qua HTTP nội bộ, chờ service_started)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>web-dashboard (nginx, chỉ depends_on api-gateway, không chờ healthy — chỉ chờ container start)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ai-service ──▶ chromadb (chờ service_started, không healthy — Chroma healthcheck riêng nhưng không phải depends_on condition)</span></span>
<span class="line"><span>publisher-service ──▶ rabbitmq (healthy)</span></span></code></pre></div><p>api-gateway là entrypoint duy nhất từ ngoài (port 8080) cho mọi client (web, mobile). business-service/ai-service/publisher-service không expose ra ngoài mạng thật trong production, nhưng compose local vẫn mở port host để debug trực tiếp (8081/8082/8083).</p><h2 id="mobile-app-expo-—-khong-nam-trong-compose" tabindex="-1">Mobile app (Expo) — không nằm trong compose <a class="header-anchor" href="#mobile-app-expo-—-khong-nam-trong-compose" aria-label="Permalink to &quot;Mobile app (Expo) — không nằm trong compose&quot;">​</a></h2><p><code>brandhub-mobile-app</code> không có Dockerfile/service trong <code>docker-compose.apps.yml</code> — chạy ngoài Docker bằng Metro bundler (<code>npm run dev</code>, mặc định port <code>8090</code> theo <code>package.json</code> — đổi khỏi mặc định Expo <code>8081</code> vì trùng port host của <code>business-service</code>). Gọi API qua <code>EXPO_PUBLIC_API_BASE_URL</code> trỏ thẳng <code>api-gateway</code> (port 8080), cùng entrypoint với web-dashboard — không có route riêng cho mobile ở gateway.</p><p>Thiết bị thật/emulator không resolve được <code>localhost</code> của máy host — <code>.env</code> phải dùng IP LAN máy chạy backend (<code>http://&lt;local-ip&gt;:8080</code>), hoặc <code>http://10.0.2.2:8080</code> khi test trên Android emulator (AVD).</p><h2 id="networking" tabindex="-1">Networking <a class="header-anchor" href="#networking" aria-label="Permalink to &quot;Networking&quot;">​</a></h2><p>Toàn bộ chung 1 bridge network <code>brandhub-network</code> (external name cố định, không prefix theo project) — cho phép service gọi nhau qua tên container (<code>http://business-service:8081</code>) bất kể compose file nào tạo ra network trước.</p><h2 id="điem-khac-biet-voi-readme-md-hien-tai" tabindex="-1">Điểm khác biệt với README.md hiện tại <a class="header-anchor" href="#điem-khac-biet-voi-readme-md-hien-tai" aria-label="Permalink to &quot;Điểm khác biệt với README.md hiện tại&quot;">​</a></h2><p><code>brandhub-infrastructure/README.md</code> mô tả sai:</p><ul><li>Nói có 1 <code>docker-compose.yml</code> — thực tế 3 file (<code>infra</code>/<code>apps</code>/<code>dev</code>), xem trên.</li><li>Nói <code>mongo</code> là container local — thực tế Atlas cloud, không có service.</li><li>Bảng port/image trong README dùng version cũ (<code>postgres:16-alpine</code>, <code>rabbitmq:3.13</code>) — thực tế <code>docker-compose.infra.yml</code> dùng <code>postgres:17-alpine</code>, <code>rabbitmq:3.12-management-alpine</code>.</li></ul><p>README chưa được cập nhật lại theo scope hiện tại — ghi nhận ở đây để không bị lẫn khi debug setup.</p>`,22)])])}const g=o(s,[["render",t]]);export{m as __pageData,g as default};
